<template>
	<transition name="soft-toast-pop">
		<view v-if="visible" class="soft-toast" :class="typeClass">
			<view class="soft-toast-mark" :class="typeMarkClass">
				<view v-if="type === 'success'" class="soft-toast-check"></view>
				<text v-else-if="type === 'warn'">!</text>
				<text v-else>·</text>
			</view>
			<text class="soft-toast-text">{{ message }}</text>
		</view>
	</transition>
</template>

<script>
export default {
	name: 'SoftToast',
	props: {
		visible: { type: Boolean, default: false },
		message: { type: String, default: '' },
		type: { type: String, default: 'success' }
	},
	computed: {
		typeClass() {
			return `soft-toast-${this.type}`;
		},
		typeMarkClass() {
			return `soft-toast-mark-${this.type}`;
		}
	}
};
</script>

<style lang="scss" scoped>
.soft-toast {
	position: fixed;
	top: 18%;
	left: 50%;
	z-index: 9999;
	display: flex;
	align-items: center;
	gap: 14rpx;
	max-width: 78%;
	padding: 18rpx 30rpx;
	border-radius: 999rpx;
	background: rgba(28, 20, 50, 0.86);
	backdrop-filter: blur(14rpx);
	-webkit-backdrop-filter: blur(14rpx);
	color: #ffffff;
	font-size: 25rpx;
	font-weight: 500;
	letter-spacing: 1rpx;
	box-shadow:
		0 18rpx 38rpx rgba(28, 20, 50, 0.28),
		inset 0 1rpx 0 rgba(255, 255, 255, 0.12);
	transform-origin: top center;
}

.soft-toast-mark {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 32rpx;
	height: 32rpx;
	border-radius: 50%;
	flex-shrink: 0;
	font-size: 26rpx;
	font-weight: 800;
	line-height: 1;
	color: #ffffff;
}

.soft-toast-mark-success {
	background: linear-gradient(135deg, #ff8ba7, #d4688a);
}

.soft-toast-mark-warn {
	background: linear-gradient(135deg, #f5b06b, #e08945);
}

.soft-toast-mark-info {
	background: linear-gradient(135deg, #8aa6f0, #6c7ad6);
}

.soft-toast-check {
	width: 16rpx;
	height: 8rpx;
	border-left: 3rpx solid #ffffff;
	border-bottom: 3rpx solid #ffffff;
	transform: rotate(-45deg) translateY(-2rpx);
}

.soft-toast-text {
	flex: 1;
	min-width: 0;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.soft-toast-pop-enter-active {
	transition:
		opacity 320ms ease-out,
		transform 360ms cubic-bezier(0.2, 0.72, 0.3, 1.08);
}

.soft-toast-pop-leave-active {
	transition:
		opacity 220ms ease-in,
		transform 240ms cubic-bezier(0.4, 0, 0.6, 1);
}

.soft-toast-pop-enter,
.soft-toast-pop-leave-to {
	opacity: 0;
	transform: translateX(-50%) translateY(-26rpx) scale(0.9);
}

.soft-toast-pop-enter-to,
.soft-toast-pop-leave {
	opacity: 1;
	transform: translateX(-50%) translateY(0) scale(1);
}
</style>
